final class HeroesCraftV5View extends BaseArcadeView {
  static final class Node{int x,y,type;boolean taken;Node(int x,int y,int type){this.x=x;this.y=y;this.type=type;}}
  private final List<Node> nodes=new ArrayList<Node>();
  private final boolean[][] seen=new boolean[15][10];
  private final Random rnd=new Random(1591L);
  private final ArcadeFx fx=new ArcadeFx();
  private int page=0,hx=2,hy=7,fromX=2,fromY=7,toX=2,toY=7,rivalX=12,rivalY=2;
  private int iron=4,cement=3,tools=1,gold=180,blueprints,contracts,artifacts,score,shop=1,weld=0,truck=0,day=1,moves=5,maxMoves=5,morale=70;
  private int ownHp=210,enemyHp=190,turn,selectedArmy,enemyType,crew0=7,crew1=3,crew2=1,guard;
  private float moveT=1,animClock,combatAnim,flash;
  private boolean moving;
  private final RectF up=new RectF(770,358,844,426),down=new RectF(770,432,844,504),left=new RectF(694,432,766,504),right=new RectF(848,432,922,504);
  private final RectF townBtn=new RectF(692,272,804,338),combatBtn=new RectF(812,272,944,338),endTurn=new RectF(700,348,944,410),mapBtn=new RectF(742,432,944,500);
  private final RectF build0=new RectF(108,390,302,458),build1=new RectF(382,390,576,458),build2=new RectF(656,390,850,458);
  private final RectF attackBtn=new RectF(710,326,944,388),defendBtn=new RectF(710,396,824,458),skillBtn=new RectF(832,396,944,458);
  HeroesCraftV5View(Context c,GateCraftGame owner){super(c,owner);generateNodes();reveal();}
  @Override public int score(){return score;}@Override public void shutdown(){super.shutdown();nodes.clear();fx.clear();}
  @Override public void restart(){page=0;ownHp=210;enemyHp=190;turn=0;combatAnim=flash=0;moving=false;moveT=1;guard=0;invalidate();}
  private void generateNodes(){nodes.clear();boolean[][] used=new boolean[15][10];used[hx][hy]=true;int[][] fixed={{5,7,0},{7,6,1},{10,4,2},{4,4,3},{11,7,4},{7,2,0},{1,5,1},{9,8,2},{12,3,3},{5,8,4},{10,1,5},{7,5,2},{2,2,3},{13,7,1},{12,6,5},{3,6,4},{9,3,0},{6,1,5}};for(int[] a:fixed){nodes.add(new Node(a[0],a[1],a[2]));used[a[0]][a[1]]=true;}for(int i=0;i<10;i++){int x=1+rnd.nextInt(13),y=1+rnd.nextInt(8);if(!used[x][y]){nodes.add(new Node(x,y,rnd.nextInt(6)));used[x][y]=true;}}}
  private void reveal(){for(int yy=Math.max(0,hy-2);yy<=Math.min(9,hy+2);yy++)for(int xx=Math.max(0,hx-2);xx<=Math.min(14,hx+2);xx++)seen[xx][yy]=true;}
  @Override void updateGame(float dt){animClock+=dt;fx.update(dt);flash=Math.max(0,flash-dt);if(moving){moveT=Math.min(1,moveT+dt*4.8f);if(moveT>=1){moving=false;hx=toX;hy=toY;reveal();collectAt(hx,hy);}}if(combatAnim>0)combatAnim=Math.max(0,combatAnim-dt);}
  @Override void drawGame(Canvas c){if(page==0)drawMap(c);else if(page==1)drawTown(c);else drawCombat(c);fx.draw(c,p);}
  private String resLine(){return "Fe "+iron+"  Cem "+cement+"  Tool "+tools+"  Gold "+gold+"  BP "+blueprints+"  Art "+artifacts;}
  private void topBar(Canvas c,String title){fill(c,Color.rgb(17,12,10),0,0,960,78);fill(c,Color.rgb(88,57,31),0,64,960,78);text(c,title,26,37,25,Color.rgb(248,218,145),Paint.Align.LEFT,true);text(c,resLine(),385,35,14,Color.WHITE,Paint.Align.LEFT,true);text(c,t("NAP","DAY","TAG","DÍA","JOUR","天","GIORNO","DIA","DZIEŃ","DAG","ZI","ДЕНЬ")+" "+day+"  "+t("LÉPÉS","MOVE","ZUG","PASO","MOUV.","移动","MOSSE","MOV.","RUCH","ZET","MIȘC.","ХОД")+" "+moves+"/"+maxMoves,385,59,13,Color.rgb(225,190,105),Paint.Align.LEFT,false);}
  private void ornateFrame(Canvas c,float l,float top,float r,float b){fill(c,Color.rgb(68,44,25),l,top,r,b);stroke(c,Color.rgb(227,193,116),4,l,top,r,b);stroke(c,Color.rgb(28,20,15),2,l+7,top+7,r-7,b-7);for(float x=l+14;x<r-10;x+=36)fill(c,Color.rgb(113,76,36),x,top+4,x+14,top+9);for(float x=l+14;x<r-10;x+=36)fill(c,Color.rgb(113,76,36),x,b-9,x+14,b-4);}
  private void drawMap(Canvas c){topBar(c,"HEROES OF CRAFT & GATES II");fill(c,Color.rgb(8,9,10),0,78,960,540);ornateFrame(c,16,90,680,524);fill(c,Color.rgb(18,22,20),27,101,669,513);float oxm=324,oym=118,tw=43,th=23;for(int y=0;y<10;y++)for(int x=0;x<15;x++){float cx=oxm+(x-y)*tw/2,cy=oym+(x+y)*th/2;int terrain=terrain(x,y),col=terrain==0?(((x+y)&1)==0?Color.rgb(59,121,59):Color.rgb(53,109,54)):terrain==1?Color.rgb(42,87,123):terrain==2?Color.rgb(111,93,55):Color.rgb(44,91,48);diamond(c,cx,cy,tw,th,col,Color.rgb(27,52,30));if(terrain==3&&((x*13+y*5)%3==0))tree(c,cx,cy-11,.72f);if(terrain==2)roadMark(c,cx,cy);if(!seen[x][y])diamond(c,cx,cy,tw,th,Color.argb(218,8,10,12),Color.rgb(12,14,16));}building(c,tileX(10,2,oxm,tw),tileY(10,2,oym,th)-28,0);building(c,tileX(12,7,oxm,tw),tileY(12,7,oym,th)-25,1);building(c,tileX(3,1,oxm,tw),tileY(3,1,oym,th)-24,2);for(Node n:nodes)if(!n.taken&&seen[n.x][n.y]){float cx=tileX(n.x,n.y,oxm,tw),cy=tileY(n.x,n.y,oym,th)-13;drawNode(c,cx,cy,n.type);}float a=moving?moveT:1f,hxv=fromX+(toX-fromX)*a,hyv=fromY+(toY-fromY)*a;drawHero(c,oxm+(hxv-hyv)*tw/2,oym+(hxv+hyv)*th/2-17,false);drawHero(c,tileX(rivalX,rivalY,oxm,tw),tileY(rivalX,rivalY,oym,th)-17,true);ornateFrame(c,692,90,948,524);fill(c,Color.rgb(30,24,20),704,103,936,257);text(c,t("VÁLLALKOZÓ","CONTRACTOR","UNTERNEHMER","CONTRATISTA","ENTREPRENEUR","承包商","IMPRESARIO","EMPREITEIRO","WYKONAWCA","AANNEMER","ANTREPRENOR","ПОДРЯДЧИК"),820,128,16,Color.rgb(248,219,147),Paint.Align.CENTER,true);portrait(c,820,184);text(c,"MORALE "+morale+"%",820,241,13,morale>40?Color.rgb(120,220,125):Color.rgb(237,115,70),Paint.Align.CENTER,true);arcadeButton(c,townBtn,t("MŰHELY","TOWN","WERKSTATT","TALLER","ATELIER","工坊","OFFICINA","OFICINA","WARSZTAT","WERKPLAATS","ATELIER","МАСТЕРСКАЯ"),Color.rgb(120,77,34),false);arcadeButton(c,combatBtn,t("HARC","COMBAT","KAMPF","COMBATE","COMBAT","战斗","LOTTA","COMBATE","WALKA","GEVECHT","LUPTĂ","БОЙ"),Color.rgb(132,47,43),false);arcadeButton(c,endTurn,t("KÖR VÉGE","END TURN","ZUG ENDE","FIN TURNO","FIN TOUR","结束回合","FINE TURNO","FIM TURNO","KONIEC TURY","EINDE BEURT","FINAL TURĂ","КОНЕЦ ХОДА"),Color.rgb(74,69,95),false);arcadeButton(c,up,"▲",Color.rgb(71,79,108),false);arcadeButton(c,down,"▼",Color.rgb(71,79,108),false);arcadeButton(c,left,"◀",Color.rgb(71,79,108),false);arcadeButton(c,right,"▶",Color.rgb(71,79,108),false);}
  private int terrain(int x,int y){if((y>=8&&x<=4)||(x==0&&y>=5)||(x==14&&y<3))return 1;if((x+y)%8==0||((x==5||x==6)&&y>2&&y<9))return 2;if((x*5+y*3)%8<=1)return 3;return 0;}
  private float tileX(int x,int y,float o,float tw){return o+(x-y)*tw/2;}private float tileY(int x,int y,float o,float th){return o+(x+y)*th/2;}
  private void roadMark(Canvas c,float x,float y){line(c,Color.rgb(150,126,71),3,x-11,y,x+11,y);}
  private void tree(Canvas c,float x,float y,float s){fill(c,Color.rgb(72,44,25),x-3*s,y,x+4*s,y+18*s);fill(c,Color.rgb(25,68,35),x-12*s,y-14*s,x+12*s,y+4*s);fill(c,Color.rgb(46,104,48),x-8*s,y-21*s,x+7*s,y-5*s);}
  private void drawNode(Canvas c,float x,float y,int kind){float bob=(float)Math.sin(animClock*4+x*.02f)*2;if(kind<=3)SpriteKit.icon(c,p,kind,x,y+bob,.72f);else if(kind==4){SpriteKit.icon(c,p,4,x,y+bob,.72f);text(c,"!",x,y-18+bob,13,Color.rgb(255,221,66),Paint.Align.CENTER,true);}else{fill(c,Color.rgb(122,83,154),x-10,y-10+bob,x+10,y+10+bob);stroke(c,Color.rgb(235,211,255),2,x-10,y-10+bob,x+10,y+10+bob);text(c,"A",x,y+5+bob,12,Color.WHITE,Paint.Align.CENTER,true);}}
  private void drawHero(Canvas c,float x,float y,boolean rival){SpriteKit.worker(c,p,x,y+27,.62f,rival?-1:1,moving&&!rival?1:0,animClock,rival);fill(c,rival?Color.rgb(218,80,65):Color.rgb(225,186,52),x-2,y-37,x+3,y-31);}
  private void portrait(Canvas c,float x,float y){fill(c,Color.rgb(18,18,22),x-44,y-44,x+44,y+44);stroke(c,Color.rgb(216,181,99),3,x-44,y-44,x+44,y+44);SpriteKit.worker(c,p,x,y+37,1.15f,1,0,animClock,false);}
  private void building(Canvas c,float x,float y,int kind){int body=kind==0?Color.rgb(146,142,129):kind==1?Color.rgb(130,82,54):Color.rgb(95,102,111);fill(c,Color.rgb(53,43,36),x-30,y-2,x+30,y+32);fill(c,body,x-27,y-30,x+27,y+28);for(int i=-22;i<=20;i+=14)fill(c,Color.rgb(74,78,81),x+i,y-39,x+i+9,y-25);fill(c,Color.rgb(45,40,37),x-6,y+3,x+7,y+28);fill(c,Color.rgb(177,121,41),x-19,y-17,x-9,y-8);fill(c,Color.rgb(177,121,41),x+9,y-17,x+19,y-8);}
  private void collectAt(int x,int y){for(Node n:nodes)if(!n.taken&&n.x==x&&n.y==y){n.taken=true;if(n.type==0){iron+=2;score+=70;}else if(n.type==1){cement+=2;score+=70;}else if(n.type==2){tools++;score+=90;}else if(n.type==3){gold+=120;blueprints++;score+=150;}else if(n.type==4){contracts++;gold+=80;score+=190;page=2;enemyHp=190+contracts*12;}else{artifacts++;morale=Math.min(100,morale+12);score+=260;}fx.sparks(360,210,12,Color.rgb(255,215,74));owner.reportScore(score);}}
  private void move(int dx,int dy){if(moving||moves<=0)return;int nx=Math.max(0,Math.min(14,hx+dx)),ny=Math.max(0,Math.min(9,hy+dy));if(nx==hx&&ny==hy)return;if(terrain(nx,ny)==1&&truck<2)return;fromX=hx;fromY=hy;toX=nx;toY=ny;moveT=0;moving=true;moves--;}
  private void doEndTurn(){day++;moves=maxMoves+truck;gold+=shop*12;iron+=weld>1?1:0;morale=Math.min(100,morale+3);moveRival();if(day%5==0){contracts++;gold+=60;fx.sparks(820,220,12,Color.rgb(255,210,70));}}
  private void moveRival(){int dx=hx>rivalX?1:-1,dy=hy>rivalY?1:-1;if(rnd.nextBoolean())rivalX=Math.max(0,Math.min(14,rivalX+dx));else rivalY=Math.max(0,Math.min(9,rivalY+dy));if(Math.abs(hx-rivalX)+Math.abs(hy-rivalY)<=1){page=2;enemyHp=205+day*3;morale=Math.max(20,morale-8);}}
  private void drawTown(Canvas c){topBar(c,t("MŰHELYFEJLESZTÉS","WORKSHOP DEVELOPMENT","WERKSTATTAUSBAU","DESARROLLO DEL TALLER","DÉVELOPPEMENT ATELIER","工坊发展","SVILUPPO OFFICINA","DESENVOLVIMENTO DA OFICINA","ROZWÓJ WARSZTATU","WERKPLAATS ONTWIKKELING","DEZVOLTARE ATELIER","РАЗВИТИЕ МАСТЕРСКОЙ"));fill(c,Color.rgb(31,47,35),0,78,960,540);for(int y=82;y<540;y+=28)for(int x=0;x<960;x+=52)diamond(c,x+(y%56),y,52,25,((x+y)/20)%2==0?Color.rgb(61,99,60):Color.rgb(55,89,55),Color.rgb(40,65,42));for(int x=24;x<936;x+=30){fill(c,Color.rgb(88,61,35),x,94,x+16,119);fill(c,Color.rgb(117,78,42),x+3,91,x+13,116);}fill(c,Color.rgb(120,102,69),420,116,540,520);for(int y=122;y<510;y+=34)fill(c,Color.rgb(142,123,82),425,y,535,y+18);townBuilding(c,207,275,0,shop);townBuilding(c,480,245,1,weld);townBuilding(c,753,278,2,truck);arcadeButton(c,build0,t("MŰHELY +","WORKSHOP +","WERKSTATT +","TALLER +","ATELIER +","工坊 +","OFFICINA +","OFICINA +","WARSZTAT +","WERKPLAATS +","ATELIER +","МАСТЕРСКАЯ +"),Color.rgb(113,73,32),false);arcadeButton(c,build1,t("HEGESZTŐ +","WELDING +","SCHWEISSEN +","SOLDADURA +","SOUDAGE +","焊接 +","SALDATURA +","SOLDA +","SPAWANIE +","LASSEN +","SUDURĂ +","СВАРКА +"),Color.rgb(82,91,103),false);arcadeButton(c,build2,t("TEHERAUTÓ +","TRUCK +","LKW +","CAMIÓN +","CAMION +","卡车 +","CAMION +","CAMINHÃO +","CIĘŻARÓWKA +","TRUCK +","CAMION +","ГРУЗОВИК +"),Color.rgb(102,72,47),false);arcadeButton(c,mapBtn,t("VISSZA A TÉRKÉPRE","BACK TO MAP","ZUR KARTE","VOLVER AL MAPA","RETOUR CARTE","返回地图","TORNA ALLA MAPPA","VOLTAR AO MAPA","WRÓĆ DO MAPY","TERUG NAAR KAART","ÎNAPOI LA HARTĂ","НАЗАД НА КАРТУ"),Color.rgb(63,79,99),false);}
  private void townBuilding(Canvas c,float x,float y,int kind,int lv){int body=kind==0?Color.rgb(151,130,98):kind==1?Color.rgb(101,112,123):Color.rgb(116,86,57);float w=75+lv*8,h=70+lv*10;fill(c,Color.argb(80,0,0,0),x-w/2+8,y+15,x+w/2+18,y+38);fill(c,body,x-w/2,y-h/2,x+w/2,y+h/2);stroke(c,Color.rgb(52,45,39),3,x-w/2,y-h/2,x+w/2,y+h/2);for(float xx=x-w/2+8;xx<x+w/2-4;xx+=22)fill(c,Color.rgb(58,63,67),xx,y-h/2-10,xx+14,y-h/2+4);fill(c,Color.rgb(51,43,37),x-10,y+10,x+11,y+h/2);for(int i=0;i<lv;i++)fill(c,Color.rgb(226,172,53),x-w/2+8+i*12,y-h/2+10,x-w/2+16+i*12,y-h/2+18);text(c,"LV "+lv,x,y+h/2+24,14,Color.WHITE,Paint.Align.CENTER,true);}
  private void upgrade(int which){int lv=which==0?shop:which==1?weld:truck,cost=100+lv*65;if(gold<cost)return;gold-=cost;if(which==0)shop++;else if(which==1)weld++;else truck++;maxMoves=5+truck;score+=120;owner.reportScore(score);fx.sparks(480,250,18,Color.rgb(255,212,73));}
  private void drawCombat(Canvas c){topBar(c,t("TAKTIKAI HARC","TACTICAL COMBAT","TAKTIKKAMPF","COMBATE TÁCTICO","COMBAT TACTIQUE","战术战斗","COMBATTIMENTO TATTICO","COMBATE TÁTICO","WALKA TAKTYCZNA","TACTISCH GEVECHT","LUPTĂ TACTICĂ","ТАКТИЧЕСКИЙ БОЙ"));fill(c,Color.rgb(39,54,42),0,78,960,540);ornateFrame(c,20,94,680,516);fill(c,Color.rgb(47,66,48),31,105,669,505);for(int gy=0;gy<6;gy++)for(int gx=0;gx<7;gx++){float cx=105+gx*83+(gy%2)*41,cy=145+gy*55;diamond(c,cx,cy,84,50,((gx+gy)&1)==0?Color.rgb(77,96,63):Color.rgb(68,87,58),Color.rgb(39,52,37));}int[] counts={crew0,crew1,crew2};for(int i=0;i<3;i++)unit(c,125+i*110,390-i*44,i,false,counts[i],selectedArmy==i);for(int i=0;i<3;i++)unit(c,590-i*100,180+i*54,i,true,Math.max(1,2+i+contracts/3),false);bar(c,60,112,ownHp,210,Color.rgb(58,183,78));bar(c,390,112,enemyHp,190+contracts*12,Color.rgb(196,57,47));if(combatAnim>0){float tt=1-combatAnim/.35f,sx=220+selectedArmy*105,sy=350-selectedArmy*40,tx=510-enemyType*70,ty=210+enemyType*45;line(c,Color.rgb(255,211,75),5,sx,sy,sx+(tx-sx)*Math.min(1,tt),sy+(ty-sy)*Math.min(1,tt));}ornateFrame(c,694,94,948,516);text(c,t("BRIGÁD","CREW","TEAM","EQUIPO","ÉQUIPE","队伍","SQUADRA","EQUIPE","EKIPA","TEAM","ECHIPĂ","БРИГАДА"),821,128,18,Color.rgb(248,218,145),Paint.Align.CENTER,true);text(c,"MORALE "+morale+"%",821,157,13,Color.rgb(235,203,110),Paint.Align.CENTER,true);text(c,t("Segéd","Helper","Helfer","Ayudante","Aide","助手","Aiutante","Ajudante","Pomocnik","Helper","Ajutor","Помощник")+" x"+crew0,715,188,13,Color.WHITE,Paint.Align.LEFT,false);text(c,t("Hegesztő","Welder","Schweißer","Soldador","Soudeur","焊工","Saldatore","Soldador","Spawacz","Lasser","Sudor","Сварщик")+" x"+crew1,715,211,13,Color.WHITE,Paint.Align.LEFT,false);text(c,t("Nehéz lakatos","Heavy smith","Schwerer Schlosser","Cerrajero pesado","Métallier lourd","重型金工","Fabbro pesante","Serralheiro pesado","Ciężki ślusarz","Zware smid","Lăcătuș greu","Тяжёлый слесарь")+" x"+crew2,715,234,13,Color.WHITE,Paint.Align.LEFT,false);arcadeButton(c,attackBtn,t("TÁMADÁS","ATTACK","ANGRIFF","ATACAR","ATTAQUER","攻击","ATTACCA","ATACAR","ATAK","AANVAL","ATAC","АТАКА"),Color.rgb(136,48,42),false);arcadeButton(c,defendBtn,t("VÉD","DEFEND","WEHR","DEFENSA","DÉFENSE","防御","DIFESA","DEFESA","OBRONA","VERDEDIG","APĂRĂ","ЗАЩИТА"),Color.rgb(59,91,126),false);arcadeButton(c,skillBtn,t("ÍV","ARC","LICHT","ARCO","ARC","电弧","ARCO","ARCO","ŁUK","BOOG","ARC","ДУГА"),Color.rgb(111,66,151),false);arcadeButton(c,mapBtn,t("TÉRKÉP","MAP","KARTE","MAPA","CARTE","地图","MAPPA","MAPA","MAPA","KAART","HARTĂ","КАРТА"),Color.rgb(66,78,96),false);if(flash>0)fill(c,Color.argb(80,255,226,130),31,105,669,505);}
  private void unit(Canvas c,float x,float y,int type,boolean enemy,int count,boolean selected){if(selected){fill(c,Color.argb(80,255,220,70),x-30,y-55,x+30,y+28);stroke(c,Color.rgb(255,221,72),2,x-30,y-55,x+30,y+28);}SpriteKit.worker(c,p,x,y,.78f,enemy?-1:1,type==2?3:0,animClock,enemy);text(c,"x"+count,x,y+18,12,Color.WHITE,Paint.Align.CENTER,true);}
  private void bar(Canvas c,float x,float y,int v,int max,int col){fill(c,Color.rgb(29,29,32),x,y,x+250,y+17);fill(c,col,x+2,y+2,x+2+246*Math.max(0,v)/(float)max,y+15);stroke(c,Color.rgb(235,226,193),1,x,y,x+250,y+17);}
  private void combatAction(int kind){if(combatAnim>0)return;int maxEnemy=190+contracts*12;if(kind==0){int dmg=23+weld*5+selectedArmy*6+artifacts*2;enemyHp-=dmg;score+=dmg*3;combatAnim=.35f;flash=.08f;fx.sparks(470,250,13,Color.rgb(255,195,70));if(enemyHp>0){int incoming=Math.max(5,16+turn/2-guard);ownHp-=incoming;guard=0;}}else if(kind==1){guard=12+shop*2;ownHp=Math.min(210,ownHp+8);morale=Math.min(100,morale+2);}else{if(tools>0){tools--;enemyHp-=44+weld*5+artifacts*3;combatAnim=.45f;fx.sparks(500,245,24,Color.rgb(97,201,255));}else return;}turn++;selectedArmy=(selectedArmy+1)%3;enemyType=(enemyType+1)%3;if(enemyHp<=0){gold+=200+contracts*25;score+=700;blueprints+=(turn%3==0?1:0);morale=Math.min(100,morale+7);enemyHp=maxEnemy;ownHp=210;page=0;owner.reportScore(score);}if(ownHp<=0){ownHp=210;enemyHp=maxEnemy;score=Math.max(0,score-150);morale=Math.max(20,morale-12);page=0;}owner.reportScore(score);}
  @Override void onGameDown(float x,float y){if(page==0){if(in(up,x,y))move(0,-1);else if(in(down,x,y))move(0,1);else if(in(left,x,y))move(-1,0);else if(in(right,x,y))move(1,0);else if(in(townBtn,x,y))page=1;else if(in(combatBtn,x,y))page=2;else if(in(endTurn,x,y))doEndTurn();}else if(page==1){if(in(build0,x,y))upgrade(0);else if(in(build1,x,y))upgrade(1);else if(in(build2,x,y))upgrade(2);else if(in(mapBtn,x,y))page=0;}else{if(in(attackBtn,x,y))combatAction(0);else if(in(defendBtn,x,y))combatAction(1);else if(in(skillBtn,x,y))combatAction(2);else if(in(mapBtn,x,y))page=0;}invalidate();}
  @Override void onGameMove(float x,float y){}@Override void onGameUp(float x,float y){}
}
